const WithNavigationRail = () => {
  const [selected, setSelected] = useState("apps");
  return (
    <AppShell
      navigation={
        <NavigationRail
          logo={
            <NavigationButton
              customIcon={
                <div className="w-full h-full bg-primary/20 flex items-center justify-center">
                  <span className="text-primary font-semibold text-lg">M</span>
                </div>
              }
              label="My App"
              variant="secondary"
              disableHoverExpand
              className="border border-primary"
            />
          }
        >
          <div className="w-full gap-2 flex flex-col">
            <NavigationButton
              icon="space_dashboard"
              label="Dashboard"
              variant="primary"
              selected={selected === "dashboard"}
              onClick={() => setSelected("dashboard")}
            />
            <NavigationButton
              icon="data_table"
              label="Your Apps"
              selected={selected === "apps"}
              onClick={() => setSelected("apps")}
            />
          </div>
          <div className="h-px rounded-full w-full bg-outline" />
          <div className="w-full gap-2 flex flex-col">
            <NavigationButton
              icon="extension"
              label="Add-ons"
              selected={selected === "addons"}
              onClick={() => setSelected("addons")}
            />
            <NavigationButton
              icon="rocket_launch"
              label="Deployment"
              selected={selected === "deployment"}
              onClick={() => setSelected("deployment")}
            />
            <NavigationButton
              icon="settings"
              label="Settings"
              selected={selected === "settings"}
              onClick={() => setSelected("settings")}
            />
          </div>
        </NavigationRail>
      }
      appSwitcher={
        <AppSwitcher
          currentApp="Account"
          logo={<div className="w-8 h-8"><Logo /></div>}
          apps={apps}
          activeAppId="account"
        />
      }
      agentSidebarContent={
        <div className="text-inverse-on-surface text-sm">
          Chat messages would appear here...
        </div>
      }
      onAgentSend={(msg) => console.log("Send:", msg)}
    >
      <DemoContent />
    </AppShell>
  );
};

