        { id: userId, role: "user", content },
        { id: agentId, role: "agent", content: "", streaming: true },
      ]);
      setTimeout(() => {
        patchMessage(agentId, {
          content: "Got it — let me look into that.",
          streaming: false,
        });
      }, 1500);
    };

    return (
